-- 40 lookups by a 64-character text key in one statement (40 index scans): a dictionary of a million strings over the cache is searched in the stream, and was parsed again for every scan once tested often
-- label: `sum(amount)` of 40 `WHERE ref = <a 64-character key>` scans in one statement, no btree on `ref`, `point_tid_columns = 'ref'`
-- ordered: yes
-- set: sift.enable_col_scan = on
--@ setup
ALTER TABLE orders ADD COLUMN ref text;
UPDATE orders SET ref = md5(id::text) || md5((id * 7)::text);
ALTER TABLE orders DROP CONSTRAINT orders_pkey;
DROP INDEX orders_col;
CREATE INDEX orders_col ON orders USING sift_col (id sift.col_int4_ops, ref sift.col_text_ops, amount sift.col_numeric_ops) WITH (point_tid_columns = 'ref')
--@ pg
